        : items_(std::move(items)), customerEmail_(std::move(customerEmail)) {}

    const std::vector<std::string>& getItems() const { return items_; }
    const std::string& getCustomerEmail() const { return customerEmail_; }

private:
    std::vector<std::string> items_;
    std::string customerEmail_;
};

