        // 3. send a confirmation email
        std::string body = "<h1>Thanks for your order</h1>";
        std::cout << "Emailing " << order.getCustomerEmail() << ": " << body << "\n";

        // 4. generate the invoice PDF
        std::cout << "Generating invoice.pdf layout...\n";
    }
};

int main() {
    OrderService service;
    Order order({"Keyboard", "Mouse"}, "buyer@example.com");
    service.placeOrder(order);
    return 0;
}

